def lexicographically_minimum_string(n, k, s):
    # Convert the string to a list of characters for easier manipulation
    s = list(s)

    # Attempt to move '0's to the left as much as possible within k moves
    for i in range(n):
        if k <= 0:
            break
        if s[i] == '1':
            continue

        # Move '0' to the left
        for j in range(i, 0, -1):
            if k <= 0:
                break
            if s[j - 1] == '0':
                break
            # Swap adjacent characters
            s[j], s[j - 1] = s[j - 1], s[j]
            k -= 1

    # Return the lexicographically smallest string
    return ''.join(s)

